#!/usr/bin/env python3
# CallFlow CRM single-file deployment build — existing CRM embedded; no scratch rebuild.
import json, os, secrets, hashlib, sqlite3, datetime, urllib.parse, base64
from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler

ROOT=os.path.dirname(os.path.abspath(__file__))
DB=os.path.join(ROOT,"callflow.db")
HTML_DATA=''
HOST=os.environ.get("HOST","0.0.0.0")
PORT=int(os.environ.get("PORT","8080"))

DEMO={
"users":[
 {"id":"a","role":"admin","name":"Admin","un":"admin","pw":"CFAdmin@2026#81","active":True}],
"clients":[],"callers":[],"campaigns":[],"scripts":[],"leads":[],"calls":[],"audit":[]
}

def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat()
def ph(p): return hashlib.sha256(("CallFlow:"+p).encode()).hexdigest()

def _pg():
    url=os.environ.get("DATABASE_URL","").strip()
    if not url:
        return None
    try:
        import psycopg
        return psycopg.connect(url)
    except Exception as e:
        raise RuntimeError("DATABASE_URL is set but PostgreSQL connection failed: "+str(e))

def db():
    pg=_pg()
    if pg:
        with pg.cursor() as cur:
            cur.execute("CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY,v JSONB NOT NULL)")
            cur.execute("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires DOUBLE PRECISION NOT NULL)")
        pg.commit()
        return pg
    c=sqlite3.connect(DB); c.row_factory=sqlite3.Row
    c.execute("CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY,v TEXT NOT NULL)")
    c.execute("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY,user_id TEXT,expires REAL)")
    c.commit(); return c

def load():
    c=db()
    pg=_pg()
    if pg:
        r=c.execute("SELECT v FROM kv WHERE k='state'").fetchone()
        if not r:
            state=json.loads(json.dumps(DEMO))
            for u in state["users"]: u["pw_hash"]=ph(u.pop("pw"))
            c.execute("INSERT INTO kv(k,v) VALUES('state',%s)",(json.dumps(state),))
            c.commit()
        else:
            state=r[0] if isinstance(r[0],dict) else json.loads(r[0])
        c.close(); return state
    r=c.execute("SELECT v FROM kv WHERE k='state'").fetchone()
    if not r:
        state=json.loads(json.dumps(DEMO))
        for u in state["users"]: u["pw_hash"]=ph(u.pop("pw"))
        c.execute("INSERT INTO kv(k,v) VALUES('state',?)",(json.dumps(state),));c.commit()
    else: state=json.loads(r["v"])
    c.close(); return state

def store(state):
    c=db()
    if _pg():
        c.execute("INSERT INTO kv(k,v) VALUES('state',%s) ON CONFLICT(k) DO UPDATE SET v=EXCLUDED.v",(json.dumps(state),))
    else:
        c.execute("UPDATE kv SET v=? WHERE k='state'",(json.dumps(state),))
    c.commit(); c.close()

def session_create(token, uid, expires):
    c=db()
    if _pg():
        c.execute("INSERT INTO sessions(token,user_id,expires) VALUES(%s,%s,%s)",(token,uid,expires))
    else:
        c.execute("INSERT INTO sessions VALUES(?,?,?)",(token,uid,expires))
    c.commit(); c.close()

def session_user(token):
    c=db()
    if _pg():
        r=c.execute("SELECT user_id,expires FROM sessions WHERE token=%s",(token,)).fetchone()
        c.close()
        return r
    r=c.execute("SELECT user_id,expires FROM sessions WHERE token=?",(token,)).fetchone()
    c.close(); return r

def session_delete(token):
    c=db()
    if _pg(): c.execute("DELETE FROM sessions WHERE token=%s",(token,))
    else: c.execute("DELETE FROM sessions WHERE token=?",(token,))
    c.commit(); c.close()

def user_by_id(state,uid): return next((u for u in state["users"] if u["id"]==uid),None)

def auth(h):
 token=h.get("Authorization","").replace("Bearer ","").strip()
 if not token:return None
 r=session_user(token)
 if not r or r[1]<__import__("time").time(): return None
 st=load(); return user_by_id(st,r[0])

def scoped(state,u):
 if u["role"]=="admin": return state
 if u["role"]=="client":
  cid=u["clientId"]; camps=[c for c in state["campaigns"] if c.get("clientId")==cid]; ids={c["id"] for c in camps}
  return {"users":[u],"clients":[x for x in state["clients"] if x["id"]==cid],"callers":[],
   "campaigns":camps,"scripts":[s for s in state["scripts"] if s.get("campaignId") in ids],
   "leads":[l for l in state["leads"] if l.get("campaignId") in ids],
   "calls":[c for c in state["calls"] if c.get("campaignId") in ids],"audit":[]}
 # caller
 rid=u["callerId"]; leads=[l for l in state["leads"] if l.get("callerId")==rid]; ids={l["id"] for l in leads}; cids={l["campaignId"] for l in leads}
 camps=[c for c in state["campaigns"] if c["id"] in cids]
 clientids={c["clientId"] for c in camps}
 return {"users":[u],"clients":[x for x in state["clients"] if x["id"] in clientids],
  "callers":[x for x in state["callers"] if x["id"]==rid],"campaigns":camps,
  "scripts":[s for s in state["scripts"] if s.get("campaignId") in cids],
  "leads":leads,"calls":[c for c in state["calls"] if c.get("leadId") in ids],"audit":[]}

def merge(state, incoming, u):
 if u["role"]=="admin":
  old={x["id"]:x for x in state["users"]}
  new_users=[]
  for raw in incoming.get("users",[]):
   x=dict(raw)
   if x["id"] in old:
    if "pw_hash" in old[x["id"]]: x["pw_hash"]=old[x["id"]]["pw_hash"]
    x.pop("pw",None)
   else:
    if x.get("pw"):
     x["pw_hash"]=ph(x.pop("pw"))
    elif not x.get("pw_hash"):
     continue
   x.setdefault("active",True)
   new_users.append(x)
  state.update({k:incoming[k] for k in ["clients","callers","campaigns","scripts","leads","calls","audit"] if k in incoming})
  state["users"]=new_users
  return
 if u["role"]=="client":
  cid=u["clientId"]; camps=[c for c in incoming.get("campaigns",[]) if c.get("clientId")==cid]
  campids={c["id"] for c in camps}
  state["campaigns"]=[c for c in state["campaigns"] if c.get("clientId")!=cid]+camps
  state["scripts"]=[s for s in state["scripts"] if s.get("campaignId") not in campids]+[s for s in incoming.get("scripts",[]) if s.get("campaignId") in campids]
  state["leads"]=[l for l in state["leads"] if l.get("campaignId") not in campids]+[l for l in incoming.get("leads",[]) if l.get("campaignId") in campids]
  state["calls"]=[c for c in state["calls"] if c.get("campaignId") not in campids]+[c for c in incoming.get("calls",[]) if c.get("campaignId") in campids]
 else:
  rid=u["callerId"]; inc_leads={l["id"]:l for l in incoming.get("leads",[]) if l.get("callerId")==rid}
  for l in state["leads"]:
   if l["id"] in inc_leads:
    l.update({k:inc_leads[l["id"]].get(k,l.get(k)) for k in ("status","followup")})
  state["calls"]=[c for c in state["calls"] if c.get("callerId")!=rid]+[c for c in incoming.get("calls",[]) if c.get("callerId")==rid]

class H(BaseHTTPRequestHandler):
 def sendj(self,obj,code=200):
  b=json.dumps(obj).encode(); self.send_response(code);self.send_header("Content-Type","application/json");self.send_header("Content-Length",str(len(b)));self.send_header("Access-Control-Allow-Origin","*");self.end_headers();self.wfile.write(b)
 def readj(self):
  n=int(self.headers.get("Content-Length","0"));return json.loads(self.rfile.read(n) or b"{}")
 def do_OPTIONS(self): self.send_response(204);self.end_headers()
 def do_GET(self):
  if self.path in ("/","/index.html","/CallFlow_CRM_Updated.html"):
   try:
    b=base64.b64decode(HTML_DATA)
    self.send_response(200)
    self.send_header("Content-Type","text/html; charset=utf-8")
    self.send_header("Content-Length",str(len(b)))
    self.end_headers()
    self.wfile.write(b)
   except Exception:
    self.send_error(404)
   return
  if self.path=="/health":
   try:
    load(); return self.sendj({"ok":True})
   except Exception as e: return self.sendj({"ok":False,"error":str(e)},500)
  if self.path=="/api/state":
   u=auth(self.headers)
   if not u:return self.sendj({"error":"Unauthorized"},401)
   st=load();return self.sendj({"user":u,"state":scoped(st,u)})
   # duplicate HTML route intentionally removed
  self.send_error(404)
 def do_POST(self):
  if self.path=="/api/login":
   x=self.readj();st=load();u=next((u for u in st["users"] if u.get("active",True) and u.get("un")==x.get("username") and u.get("pw_hash")==ph(x.get("password",""))),None)
   if not u:return self.sendj({"error":"Invalid username/password"},401)
   t=secrets.token_urlsafe(32);session_create(t,u["id"],__import__("time").time()+86400)
   return self.sendj({"token":t,"user":u,"state":scoped(st,u)})
  if self.path=="/api/logout":
   t=self.headers.get("Authorization","").replace("Bearer ","").strip();session_delete(t);return self.sendj({"ok":True})
  self.send_error(404)
 def do_PUT(self):
  if self.path!="/api/state":return self.send_error(404)
  u=auth(self.headers)
  if not u:return self.sendj({"error":"Unauthorized"},401)
  try:
   st=load();merge(st,self.readj(),u)
   store(st);return self.sendj({"ok":True,"state":scoped(st,u)})
  except Exception as e:return self.sendj({"error":str(e)},400)

if __name__=="__main__":
 db(); print(f"CallFlow CRM running on http://0.0.0.0:{PORT}")
 ThreadingHTTPServer((HOST,PORT),H).serve_forever()
